WITH filtered_accounts AS (SELECT * FROM accounts WHERE account_type IN ('SAVINGS', 'CREDIT', 'LOAN')), summary AS (SELECT CASE WHEN balance >= 65000 THEN 'high' WHEN balance >= 31000 THEN 'mid' ELSE 'low' END AS balance_bucket, MAX(opened_date) AS latest_opened_date FROM filtered_accounts GROUP BY CASE WHEN balance >= 65000 THEN 'high' WHEN balance >= 31000 THEN 'mid' ELSE 'low' END) SELECT balance_bucket, latest_opened_date FROM summary ORDER BY balance_bucket;
